return [{
  json: {
    body: {
      post: {
        ID: `sample-video-${Date.now()}`,
        post_title: 'Как еженедельный прогноз помогает управлять денежным потоком',
        post_content: 'Демонстрационная компания по понедельникам сверяет ожидаемые поступления, просроченные счета и ближайшие платежи. Такой ритм заранее показывает риск кассового разрыва и помогает назначить ответственных за действия.',
        post_status: 'publish',
        link: 'https://example.com/sample-video-source/'
      }
    }
  }
}];

const body = $json.body || $json || {};
const post = body.post || body || {};

const rawId =
  post.ID ||
  post.id ||
  post.post_id ||
  post.postId ||
  body.ID ||
  body.id ||
  body.post_id ||
  body.postId ||
  Date.now();

const postId = String(rawId).trim();

const rawTitle =
  post.post_title ||
  post.title ||
  body.post_title ||
  body.title ||
  '';

const title = String(rawTitle || 'Без заголовка').trim();

let content = String(
  post.post_content ||
  post.content ||
  post.description ||
  body.post_content ||
  body.content ||
  body.description ||
  ''
).trim();

content = content
  .replace(/<script[\s\S]*?<\/script>/gi, '')
  .replace(/<style[\s\S]*?<\/style>/gi, '')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/g, ' ')
  .replace(/&amp;/g, '&')
  .replace(/&quot;/g, '"')
  .replace(/&#039;/g, "'")
  .replace(/&laquo;/g, '«')
  .replace(/&raquo;/g, '»')
  .replace(/&mdash;/g, '—')
  .replace(/\s+/g, ' ')
  .trim();

if (!content && !String(rawTitle || '').trim()) {
  throw new Error('Нет текста/заголовка входящего поста');
}

const sourceUrl =
  post.guid?.rendered ||
  post.link ||
  body.link ||
  post.url ||
  body.url ||
  '';

return {
  json: {
    post_id: postId,
    title,
    content,
    source_url: sourceUrl,
    wp_status: post.post_status || post.status || body.post_status || body.status || '',
    webhook_secret:
      $json.headers?.['x-content-ops-secret'] ||
      body.secret || body.token || body.webhook_secret || '',
    received_at: new Date().toISOString()
  }
};

const isManualExecution = $execution.mode === 'manual';
const expectedSecret = String($vars.CONTENT_OPS_WEBHOOK_SECRET || '').trim();
const providedSecret = String($json.webhook_secret || '').trim();

const safe = { ...$json };
delete safe.webhook_secret;

if (!isManualExecution && !expectedSecret) {
  return {
    json: {
      ...safe,
      should_continue: false,
      skip_reason: 'CONTENT_OPS_WEBHOOK_SECRET is not configured'
    }
  };
}

if (!isManualExecution && providedSecret !== expectedSecret) {
  return {
    json: {
      ...safe,
      should_continue: false,
      skip_reason: 'Invalid webhook secret'
    }
  };
}

const status = String($json.wp_status || '').toLowerCase().trim();
if (status && !['publish', 'published'].includes(status)) {
  return {
    json: {
      ...safe,
      should_continue: false,
      skip_reason: `Post is not published. wp_status=${status}`
    }
  };
}

return {
  json: {
    ...safe,
    should_continue: true,
    skip_reason: ''
  }
};

const base = $('Validate Secret, Status, and Idempotency Key').item.json;
const rows = $input.all()
  .map(i => i.json || {})
  .filter(r => r && Object.keys(r).length && r.post_id);

const existing = rows[0] || null;

if (!base.should_continue) {
  return { json: base };
}

if (existing) {
  return {
    json: {
      ...base,
      should_continue: false,
      skip_reason: `post_id=${base.post_id} уже есть в Supabase со статусом ${existing.status || 'unknown'}`,
      existing_job: existing
    }
  };
}

return {
  json: {
    ...base,
    should_continue: true,
    skip_reason: '',
    existing_job: null
  }
};

const base = $('Evaluate Existing Job').item.json;
const created = $input.first()?.json || null;

return {
  json: {
    ...base,
    supabase_job: created
  }
};

messages.content:
=Ты — режиссёр, редактор и voice director проекта Business Media Project.

Нужно создать РОВНО ТРИ разные версии одного исходного поста для трёх сеток аккаунтов.
Все три ролика должны быть выполнены в ОДНОМ И ТОМ ЖЕ премиальном кинематографичном уровне, в едином профессиональном визуальном стиле.

КЛЮЧЕВОЙ ПРИНЦИП:
НЕ делай три разных уровня/жанра качества.
НЕ делай одну версию аналитической, вторую киношной, третью клиповой.
Все три — premium cinematic expert social video.
Различаются только:
- смысловой угол;
- hook;
- порядок аргументов;
- точный текст речи;
- эмоциональная дуга;
- конкретный B-roll;
- отдельные тексты соцсетей.

ЕДИНЫЙ ВИЗУАЛЬНЫЙ СТИЛЬ:
- начало: ведущий сразу в кадре, полукрупный или близкий план, прямой контакт;
- мягкий профессиональный боковой/фронтально-боковой свет;
- фон слегка расфокусирован, премиальный и реалистичный;
- на хуке допускается короткий быстрый релевантный B-roll;
- дальше плавная смена крупности: close-up на ключевых мыслях, medium shot на объяснениях;
- B-roll появляется только когда он усиливает конкретную произнесённую мысль;
- ведущий остаётся главным героем и отчётливо появляется в начале и в конце;
- визуалы должны давать ощущение «взгляда изнутри бизнеса», а не случайного stock montage;
- цвета естественные, слегка тёплые/кинематографичные;
- никаких дешёвых TikTok-эффектов, Breaking News, телеканальных плашек, хаоса и лишней графики.

ФАКТЫ:
- только русский язык;
- используй ТОЛЬКО факты исходного поста;
- не выдумывай цифры, даты, имена, причины, обещания, цитаты или выводы;
- не делай сенсацию из нейтральной темы.

ДЛИТЕЛЬНОСТЬ — КРИТИЧЕСКИЙ CREDIT-SAFE ЛИМИТ ДО 30 СЕКУНД:
- каждый spoken_script должен содержать ориентировочно 30–36 русских слов ДО финального CTA;
- абсолютный максимум — 36 слов ДО CTA;
- можно писать короче, если смысл сохраняется; нижнего лимита нет;
- downstream добавит фиксированный CTA из 8 слов, поэтому общий текст останется примерно до 44 слов;
- выбери только ОДНУ главную мысль и 1–2 самых сильных факта исходного поста;
- НЕ пересказывай весь исходный текст;
- не повторяй одну мысль разными словами;
- не добавляй вступления, выводы или паузы ради длины;
- HeyGen должен получить короткий сценарий, рассчитанный примерно на 22–28 секунд естественной речи и НИКОГДА не должен намеренно растягивать его до 30+ секунд;
- после HeyGen FFmpeg дополнительно ускоряет минимум в 1.2 раза;
- финальный MP4 обязан быть не длиннее 30.0 секунды.

ЖИВАЯ РУССКАЯ РЕЧЬ:
- звучит как реальный предприниматель/эксперт, говорящий одному человеку;
- тёпло, уверенно, разговорно, выразительно;
- чередуй короткие и средние предложения;
- используй запятые, тире, двоеточия, точки, вопросы как естественные подсказки просодии;
- МНОГОТОЧИЯ ЗАПРЕЩЕНЫ: не использовать «…», "..", "...";
- не добавлять длинные искусственные паузы;
- не использовать канцелярит и дикторский ритм;
- CTA в самом конце spoken_script ТОЧНО:
«Подписывайся на канал, чтобы не пропустить новые разборы.»

ПРОИЗНОШЕНИЕ / УДАРЕНИЯ:
- spoken_script — чистый текст для визуального использования;
- pronunciation_script — слово в слово тот же текст и та же пунктуация;
- единственное разрешённое отличие pronunciation_script — знак U+0301 сразу ПОСЛЕ ударной гласной в потенциально проблемных словах;
- ставь ударение только если есть реальный риск ошибки TTS;
- если не уверен — не ставь;
- U+0301 существует ТОЛЬКО для скрытой TTS-инструкции и никогда не должен быть визуальным текстом.

DELIVERY_DIRECTION:
Для каждого ролика дай конкретную эмоциональную дугу.
Пример логики: начало — лёгкое удивление/вовлечение; объяснение — спокойнее и обстоятельнее; перечисление — живее; финал — уверенно и мягко.
Адаптируй под конкретную тему, не копируй механически.

VISUAL_DIRECTION:
Для каждого ролика конкретно опиши:
- стартовый план;
- свет;
- фон;
- где close-up, где medium shot;
- где появляется B-roll и зачем;
- каким должен быть ритм;
- каким кадром возвращаемся к ведущему в финале.

B-ROLL:
4–7 конкретных визуальных сцен/объектов, которые прямо подтверждают речь.
Никакого случайного стока.

ON-SCREEN TEXT:
- hook_overlay: 1–3 целых слова, желательно до 26 символов;
- остальные overlay — максимум 2–4 целых слова;
- никаких многоточий;
- никаких разрывов слова посередине;
- никаких hyphenation типа «ПРОМЫШЛ / ЕННЫЙ».

SUBTITLES:
- визуально чистый русский текст БЕЗ U+0301;
- максимум 2 строки;
- целые слова;
- центральная safe-zone;
- не перекрывать лицо.

ОПИСАНИЯ:
YouTube: title до 60 символов, description 100–240, до 5 hashtags.
Instagram: description 100–240, до 5 hashtags.
TikTok: description 100–220, до 5 hashtags.
Threads: description 100–240, до 5 hashtags.
Тексты трёх сеток должны отличаться.

ВЕРНИ СТРОГО JSON БЕЗ MARKDOWN:
