parameters.jsCode:
function stripStressMarks(v){ return String(v ?? '').replace(/\u0301/g,''); }
const input = $input.item.json;
let content = input.choices?.[0]?.message?.content || input.message?.content || input.content || input.output?.[0]?.content?.[0]?.text || '';
content = String(content).replace(/```json/gi,'').replace(/```/g,'').trim();
let parsed;
try { parsed = JSON.parse(content); } catch (e) {
  const m = content.match(/\{[\s\S]*\}/);
  if (!m) throw new Error('OpenAI не вернул JSON: ' + content.slice(0,700));
  parsed = JSON.parse(m[0]);
}

const base = $('Merge Processing Job Context').item.json;
const CTA = 'Подписывайся на канал, чтобы не пропустить новые разборы.';
const STRESS = '\u0301';

function clean(v){
  return String(v??'')
    .replace(/[\u0000-\u001F\u007F]/g,' ')
    .replace(/\s+/g,' ')
    .trim();
}
function cleanSpeech(v){
  return String(v??'')
    .replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/g,' ')
    .replace(/[ \t]+/g,' ')
    .replace(/\n{3,}/g,'\n\n')
    .trim();
}
function stripStress(v){
  return String(v??'').normalize('NFD').replace(/\u0301/g,'').normalize('NFC');
}
function countWords(v){
  return (String(v||'').match(/[\p{L}\p{N}]+(?:-[\p{L}\p{N}]+)?/gu)||[]).length;
}
function hashtags(v,max=5){
  const a=Array.isArray(v)?v:String(v||'').split(/[\s,;]+/);
  const out=[]; const seen=new Set();
  for(let x of a){
    x=clean(x).replace(/^#+/,'').replace(/[^\p{L}\p{N}_]/gu,'');
    if(!x||/^новости$/iu.test(x))continue;
    const t='#'+x,k=t.toLowerCase();
    if(seen.has(k))continue;
    seen.add(k); out.push(t);
    if(out.length>=max)break;
  }
  return out.join(' ');
}
function shortText(v,max){
  let s=clean(v).replace(/…+/gu,'.').replace(/\.{2,}/g,'.');
  if(s.length<=max)return s;
  const parts=s.split(/(?<=[.!?])\s+/u);
  let o='';
  for(const p of parts){const n=o?o+' '+p:p;if(n.length>max)break;o=n;}
  return o||s.slice(0,max).replace(/\s+\S*$/u,'').trim();
}
function overlayText(v,max=26){
  let s=clean(v).replace(/…+/gu,'').replace(/\.{2,}/g,'.').replace(/[.!?;:,]+$/g,'').trim();
  const words=s.split(/\s+/).filter(Boolean).slice(0,4);
  let out='';
  for(const w of words){const next=out?out+' '+w:w;if(next.length>max)break;out=next;}
  return out || words[0] || '';
}

const reps=[
  ['ФНС России','Федеральная налоговая служба России'],
  ['ФНС','Федеральная налоговая служба'],
  ['ИП','индивидуальный предприниматель'],
  ['ООО','общество с ограниченной ответственностью'],
  ['НДС','налог на добавленную стоимость'],
  ['НДФЛ','налог на доходы физических лиц'],
  ['УСН','упрощенная система налогообложения'],
  ['ПСН','патентная система налогообложения'],
  ['ОСНО','общая система налогообложения'],
  ['ЕНС','единый налоговый счет'],
  ['ККТ','контрольно-кассовая техника'],
  ['ЦБ РФ','Центральный банк России'],
  ['ЦБ','Центральный банк']
];

function removeOldCTA(s){
  return String(s||'')
    .replace(/Хочешь узнать больше о предпринимательстве[?!,. …—-]*переходи в шапку профиля\.?/giu,'')
    .replace(/Хочешь узнать больше о предпринимательстве[?!,. …—-]*/giu,'')
    .replace(/Переходи в шапку профиля\.?/giu,'')
    .replace(/Ссылка в (?:шапке )?профиля\.?/giu,'')
    .replace(/Ссылка в описании\.?/giu,'')
    .replace(/Подписывайся на канал, чтобы не пропустить новые разборы\.?/giu,'')
    .trim();
}

function expandAbbreviations(s){
  for(const [a,b] of reps){
    s=s.replace(new RegExp(`(^|[^\\p{L}\\p{N}_])${a.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')}(?=$|[^\\p{L}\\p{N}_])`,'giu'),`$1${b}`);
  }
  return s;
}

function baseSpeech(v){
  let s=removeOldCTA(cleanSpeech(v))
    .replace(/…+/gu,'.')
    .replace(/\.{2,}/g,'.')
    .replace(/\s+([,.;:!?])/g,'$1')
    .replace(/([,.;:!?])(?=[^\s»”])/g,'$1 ')
    .trim();
  s=expandAbbreviations(s)
    .replace(/\s+([,.;:!?])/g,'$1')
    .replace(/([,.;:!?])(?=[^\s»”])/g,'$1 ')
    .trim();
  if(s && !/[.!?]$/u.test(s)) s += '.';
  return s;
}

function makePronunciation(rawPron, cleanBase){
  if(!rawPron) return cleanBase;
  let p=baseSpeech(rawPron);
  // pronunciation_script is accepted ONLY if it differs from clean script by U+0301 stress marks.
  const a=stripStress(p).replace(/\s+/g,' ').trim();
  const b=stripStress(cleanBase).replace(/\s+/g,' ').trim();
  if(a !== b) return cleanBase;
  // Reject suspicious over-annotation: stress marks should be sparse, not on every word.
  const marks=(p.match(/\u0301/g)||[]).length;
  const words=(p.match(/[\p{L}Ёё]+/gu)||[]).length;
  if(words>0 && marks > Math.max(12, Math.ceil(words*0.22))) return cleanBase;
  return p;
}

function makePlainPronunciationHints(accented){
  // ВАЖНО: actual U+0301 существует только внутри этой функции.
  // На выходе — обычный текст БЕЗ любых accent characters.
  const text=String(accented||'').normalize('NFD');
  const tokens=text.match(/[\p{L}\p{M}-]+/gu)||[];
  const vowels=new Set(Array.from('аеёиоуыэюяАЕЁИОУЫЭЮЯ'));
  const out=[];
  const seen=new Set();

  for(const token of tokens){
    if(!token.includes('\u0301')) continue;

    let syllable=0;
    let stressed=0;
    const chars=Array.from(token);

    for(let i=0;i<chars.length;i++){
      const ch=chars[i];
      if(vowels.has(ch)){
        syllable++;
        // Accent may follow the vowel immediately or after another combining mark (e.g. ё decomposition).
        let j=i+1;
        while(j<chars.length && /\p{M}/u.test(chars[j])){
          if(chars[j]==='\u0301') stressed=syllable;
          j++;
        }
      }
    }

    const word=token
      .replace(/[\u0300\u0301\u0340\u0341]/g,'')
      .normalize('NFC');

    if(!word || !stressed) continue;
    const key=word.toLowerCase();
    if(seen.has(key)) continue;
    seen.add(key);

    out.push(`${word}: ударение на ${stressed}-м слоге`);
    if(out.length>=12) break;
  }

  return out;
}

if(!Array.isArray(parsed.variants)||parsed.variants.length!==3) throw new Error('Нужно ровно 3 variants');
const branches=new Set();
const variants=parsed.variants.map((v,i)=>{
  const branch=Number(v.branch)||i+1;
  branches.add(branch);
  const baseSc=baseSpeech(v.spoken_script);
  if(!baseSc || baseSc.length < 10) throw new Error(`Сетка ${branch}: spoken_script пустой`);
  const pronBase=makePronunciation(v.pronunciation_script, baseSc);
  const pronunciationHints=makePlainPronunciationHints(pronBase);

  // Ограничение длительности: блокируем слишком длинный текст до запроса HeyGen. Нижнего лимита нет.
  const bodyWordCount=countWords(baseSc);
  if(bodyWordCount>36){
    throw new Error(`CREDIT_GUARD MAX30: сетка ${branch} содержит ${bodyWordCount} слов до CTA. Максимум 36. HeyGen НЕ будет вызван.`);
  }

  const spoken=stripStress(`${baseSc} ${CTA}`.replace(/\s+/g,' ').trim());
  const totalWordCount=countWords(spoken);
  if(totalWordCount>44){
    throw new Error(`CREDIT_GUARD MAX30: сетка ${branch} содержит ${totalWordCount} слов вместе с CTA. Максимум 44. HeyGen НЕ будет вызван.`);
  }

  return {
    branch,
    concept:stripStress(clean(v.concept)),
    spoken_script:spoken,                  // Единственный текст речи, который идёт в HeyGen: БЕЗ accent chars
    pronunciation_script:spoken,           // Downstream тоже БЕЗ accent chars
    tts_script:spoken,                     // Downstream тоже БЕЗ accent chars
    pronunciation_hints:pronunciationHints,// Только plain-language: «слово: ударение на 2-м слоге»
    pronunciation_marks_count:pronunciationHints.length,
    script_words_before_cta:bodyWordCount,
    script_words_total:totalWordCount,
    delivery_direction:stripStress(clean(v.delivery_direction || (branch===1?'Тёплая уверенная экспертная подача с естественными смысловыми акцентами.':branch===2?'Личная вовлечённая подача с живой эмоциональной дугой.':'Энергичная, любопытная и уверенная подача без спешки.'))),
    hook_overlay:stripStress(overlayText(v.hook_overlay,26)),
    visual_direction:stripStress(clean(v.visual_direction)),
    broll_keywords:(Array.isArray(v.broll_keywords)?v.broll_keywords:[]).map(x=>stripStress(clean(x))).filter(Boolean).slice(0,7),
    youtube_title:shortText(v.youtube?.title||v.hook_overlay||base.title,60),
    youtube_desc:shortText(v.youtube?.description,240),
    youtube_hashtags:hashtags(v.youtube?.hashtags),
    instagram_text:shortText(v.instagram?.description,240),
    instagram_hashtags:hashtags(v.instagram?.hashtags),
    tiktok_text:shortText(v.tiktok?.description,220),
    tiktok_hashtags:hashtags(v.tiktok?.hashtags),
