const base=$('Parse and Validate 3 Content Sets').item.json;
const stylesRaw=$('HeyGen: List Available Styles').item.json;
const styles=(stylesRaw.data||stylesRaw||[]).filter(x=>x&&x.style_id);
const portrait=styles.filter(x=>String(x.aspect_ratio||'').includes('9:16')||/portrait/i.test(String(x.aspect_ratio||'')));
const pool=(portrait.length>=3?portrait:styles).slice();
const BRAND_KIT_ID=String($json.brand_kit_id||'').trim();

// Configured avatar IDs.
const AVATARS = [
  String($vars.HEYGEN_AVATAR_ID_1 || '').trim(),
  String($vars.HEYGEN_AVATAR_ID_2 || '').trim(),
  String($vars.HEYGEN_AVATAR_ID_3 || '').trim()
];
const VOICE = String($vars.HEYGEN_VOICE_ID || '').trim();

// HeyGen сейчас отклоняет prompt > 10000 символов.
// Держим безопасный запас, чтобы система не зависела от пограничного значения.
