}

function h(s){
  let x=100000001;
  for(const c of String(s)){x^=c.charCodeAt(0);x=Math.imul(x,16777619);}
  return x>>>0;
}

function clean(v){
  return String(v??'')
    .replace(/[\u0000-\u001F\u007F]/g,' ')
    .replace(/\s+/g,' ')
    .trim();
}

function stripStress(v){
  // Снимаем только accent/stress marks. Не удаляем U+0308, поэтому «ё» сохраняется.
  return String(v ?? '')
    .normalize('NFD')
    .replace(/[\u0300\u0301\u0340\u0341]/g,'')
    .normalize('NFC');
}

function deepStripStress(value){
  if(Array.isArray(value)) return value.map(deepStripStress);
  if(value && typeof value==='object'){
    const out={};
    for(const [k,v] of Object.entries(value)) out[k]=deepStripStress(v);
    return out;
  }
  return typeof value==='string' ? stripStress(value) : value;
}

function countWords(v){
  return (String(v||'').match(/[\p{L}\p{N}]+(?:-[\p{L}\p{N}]+)?/gu)||[]).length;
}

function limitWhole(v,max){
  const s=clean(v);
  if(s.length<=max) return s;
  const words=s.split(/\s+/).filter(Boolean);
  const out=[];
  let len=0;
  for(const w of words){
    const next=len+(out.length?1:0)+w.length;
    if(next>max) break;
    out.push(w);
    len=next;
  }
  return out.join(' ');
}

const avatars=AVATARS.slice()
  .sort((a,b)=>h(base.post_id+a)-h(base.post_id+b))
  .slice(0,3);

// Use one consistent render style across all three videos.
const PRIMARY_STYLE_ID=String($json.primary_style_id||'').trim();
function choosePrimaryStyle(){
  if(PRIMARY_STYLE_ID) return PRIMARY_STYLE_ID;
  const priorities=['cinematic','professional'];
  for(const tag of priorities){
    const x=pool.find(s=>(s.tags||[]).some(t=>String(t).toLowerCase()===tag));
    if(x) return x.style_id;
