function buildPrompt(v,speech,level){
  // Dynamic fields are the ONLY parts we shorten if the 10k API limit is approached.
  // The shared style instructions stay unchanged.
  const delivery=limitWhole(v.delivery_direction, level===0?650:(level===1?430:260));
  const concept=limitWhole(v.concept, level===0?360:(level===1?240:160));
  const directing=limitWhole(v.visual_direction, level===0?1200:(level===1?720:360));
  const broll=(v.broll_keywords||[])
    .map(x=>stripStress(limitWhole(x,90)))
    .filter(Boolean)
    .slice(0,level===0?7:(level===1?5:3));

  return `Create ONE premium vertical 9:16 SHORT-FORM expert social video in Russian. Use the exact supplied script and NEVER add spoken words, filler, repeated conclusions, extra narration or long pauses. Keep natural human pacing. Target the HeyGen render around 22–28 seconds and NEVER intentionally pad it beyond 30 seconds. The script is deliberately short to protect HeyGen credits. A separate FFmpeg step will apply at least 1.2x speed. Do not add pauses, extra narration, extra spoken CTA, intros or outros that increase duration.

VOICE LOCK — ABSOLUTE REQUIREMENT:

- Use the exact assigned HeyGen voice ID ${VOICE} for 100% of all spoken audio.
- The assigned avatar already has this same voice set as its default, but the explicit voice_id must still be honored.
- Use ONE narrator only. Never introduce a second narrator, character voice, dialogue voice, stock voice, replacement voice, or alternate TTS voice.
- If the video cuts to B-roll, the SAME locked narration continues.
- Do not pitch-shift, time-stretch, vocode, add reverb, chorus, voice filters, or any effect that changes the narrator's timbre.
- Keep the narration clean, dry, full-range and natural. Background music must stay clearly below speech and must not trigger audible pumping or distortion.

PRONUNCIATION GUIDE — NEVER DISPLAY:
${(v.pronunciation_hints||[]).length ? (v.pronunciation_hints||[]).map(x=>'- '+stripStress(x)).join('\n') : '- No special pronunciation hints.'}
These are hidden pronunciation instructions only. Never render this guide as captions, titles, overlays, labels, graphics or B-roll text.

USE THIS EXACT CLEAN VOICEOVER SCRIPT VERBATIM. It contains NO stress/accent marks. Preserve punctuation because it is intentional prosody guidance. Do not paraphrase, shorten, expand, or add spoken words:
“${stripStress(speech)}”

DELIVERY / EMOTION:
${delivery}
Speak like a real expert talking to one person: warm, confident, conversational and expressive, never robotic or announcer-like. Respect commas and dashes as natural micro-pauses; questions must sound like real questions; short sentences should land as emphasis. Vary emphasis and cadence naturally. Do not rush. NEVER add ellipses or long dramatic pauses.

VISUAL CONCEPT FOR GRID ${v.branch}:
${concept}

DIRECTING:
${directing}
Use consistent editorial framing: start with a clear medium-close or close shot of the presenter, professional soft side or front-side light, slightly defocused premium realistic background. On the hook, use a short burst of directly relevant B-roll when useful. Then alternate close framing on key statements with medium framing on explanations. B-roll must appear only when it supports the exact sentence being spoken. Return clearly to the presenter for the conclusion and CTA. Keep the feeling cinematic, warm, realistic and like a privileged look inside real business.

Suggested B-roll/visual assets:
${broll.map(x=>'- '+x).join('\n')}

VISUAL QUALITY:

- premium business editorial aesthetic;
- highest practical rendering quality, clean modern cinematic lighting, realistic materials and skin;
- purposeful visual changes and relevant B-roll only when they support the spoken fact;
- no random stock footage, cheesy transitions, clutter, fake TV-news graphics, low-quality AI artifacts or unnecessary scene spam;
- avatar remains the recognisable presenter and appears clearly at the start and end;
- natural facial motion and restrained confident gestures;
- never sacrifice visual quality to make generation faster.

AUDIO MIX:

- narration is always the dominant element;
- subtle professional background music only;
- strong but smooth ducking under narration;
- no mastering effect that changes the voice identity.

ON-SCREEN TEXT:
Hook “${stripStress(limitWhole(v.hook_overlay,26))}” may appear briefly; all other overlay text must be very short (2–4 whole words) and factual.
NEVER split, hyphenate, wrap or break a word in the middle. Line breaks are allowed only between complete words. If text does not fit, shorten the phrase, reduce font size or reflow the composition.

CRITICAL CROSS-PLATFORM SAFE ZONE FOR TIKTOK / INSTAGRAM REELS / YOUTUBE SHORTS / VK CLIPS:

- Russian captions are REQUIRED for the full narration.
- Captions must use only clean Russian text with no stress/accent marks.
- Captions must stay in the CENTRAL safe rectangle, approximately 10–82% of frame width and 40–62% of frame height.
- NEVER place captions in the bottom 30% of the frame.
- NEVER place critical text in the rightmost 18% of the frame.
- Do not put key text in the top 12%.
- Maximum 2 lines, usually 2–5 whole words per caption block, large high-contrast mobile-readable type.
- NEVER split a word between caption lines.
- Captions have layout priority: move/reframe the avatar or visuals so captions never cover the face.
- Keep all important titles and graphics away from app UI zones at the top/bottom/right edges.

Do not create a logo intro. Start immediately on the hook. Keep pacing natural and human.`;
}

const sortedVariants=base.variants.sort((a,b)=>a.branch-b.branch);

// Use the same prompt-detail level for all three videos.
let batchPromptMode=0;
for(const v of sortedVariants){
  const speech=stripStress(String(v.spoken_script||v.tts_script||'').trim());
  if(buildPrompt(v,speech,0).length>MAX_PROMPT_CHARS){ batchPromptMode=1; break; }
}
if(batchPromptMode===1){
  for(const v of sortedVariants){
    const speech=stripStress(String(v.spoken_script||v.tts_script||'').trim());
    if(buildPrompt(v,speech,1).length>MAX_PROMPT_CHARS){ batchPromptMode=2; break; }
  }
}

return sortedVariants.map((v,i)=>{
  const style_id=primaryStyleId;
  const speech=stripStress(String(v.spoken_script||v.tts_script||'').trim());

  // Check the credit limit immediately before building the HeyGen request.
  // A workflow run may create at most ONE HeyGen session for this branch.
  const speechWords=countWords(speech);
  if(speechWords>44){
    throw new Error(`CREDIT_GUARD PRE-HEYGEN MAX30: сетка ${v.branch}, ${speechWords} слов вместе с CTA. Максимум 44. POST заблокирован.`);
  }

  // Визуальная версия текста БЕЗ знаков ударения.
  const visible_script=stripStress(String(v.spoken_script||v.tts_script||'').trim());
  v.spoken_script=visible_script;
  v.hook_overlay=stripStress(v.hook_overlay||'');

  let mode=batchPromptMode;
  let prompt=buildPrompt(v,speech,mode);

  // Резервная ветка нужна только при изменении данных между предварительной проверкой и сборкой запроса.
  if(prompt.length>MAX_PROMPT_CHARS){
    mode=Math.max(1,mode);
    prompt=buildPrompt(v,speech,mode);
  }
  if(prompt.length>MAX_PROMPT_CHARS){
    mode=2;
    prompt=buildPrompt(v,speech,mode);
  }

  // Keep the selected primary style.
  // Если даже после сокращения динамических режиссёрских полей prompt не влезает,
  // останавливаемся ДО HeyGen: сам exact script не режем, style instructions не ухудшаем.
  if(prompt.length>MAX_PROMPT_CHARS){
    throw new Error(
      `HeyGen prompt превышает безопасный лимит: ${prompt.length} символов. ` +
      `Exact script: ${speech.length}. Речь и инструкции по стилю сохранены.`
    );
  }

  // Final check: no stress or accent character may leave this node.
  prompt=stripStress(prompt);

  let body={
    prompt,
    mode:'generate',
    avatar_id:avatars[i],
    voice_id:VOICE,
    orientation:'portrait',
    incognito_mode:false
  };
  if(style_id) body.style_id=style_id;
  if(BRAND_KIT_ID) body.brand_kit_id=BRAND_KIT_ID;
  body=deepStripStress(body);

  const serialized=JSON.stringify(body).normalize('NFD');
  if(/[\u0300\u0301\u0340\u0341]/.test(serialized)){
    throw new Error(`STRICT NO-STRESS gate: accent character обнаружен в HeyGen request body, сетка ${v.branch}`);
  }

  return {
    json:{
      ...base,
      ...v,
      avatar_id:avatars[i],
      voice_id:VOICE,
      style_id,
      brand_kit_id:BRAND_KIT_ID,
      heygen_prompt:stripStress(prompt),
      heygen_prompt_chars:prompt.length,
      heygen_prompt_mode:mode,
      visible_script_no_stress:visible_script,
      visible_hook_no_stress:stripStress(v.hook_overlay||''),
      heygen_request_body:body,
      render_attempt:1
    }
  };
});

const groups=$input.all().map(i=>i.json).sort((a,b)=>a.branch-b.branch);
const base=$('Merge Processing Job Context').item.json;
function getUrl(x){const r=x?.result||{};return String(x?.publicUrl||r.publicUrl||r.url||r.mediaUrl||r.data?.publicUrl||r.data?.url||r.data?.mediaUrl||r.result?.publicUrl||r.result?.url||'').trim();}
const labels={youtube:'YouTube',instagram:'Instagram',tiktok:'TikTok',threads:'Threads',vk:'VK'};
const flat=[];let text='';
for(const g of groups){
  text+=(text?'\n\n':'')+`Сетка ${g.branch}`;
  const order=g.branch===1?['youtube','instagram','tiktok','threads','vk']:['youtube','instagram','tiktok','threads'];
