const base=$('HeyGen 1: Finalize Video').item.json;
function clean(v){return String(v??'').replace(/[\u0000-\u001F\u007F]/g,' ').replace(/\s+/g,' ').trim();}
function clip(v,max){const s=clean(v);if(s.length<=max)return s;const parts=s.split(/(?<=[.!?…])\s+/u).filter(Boolean);let out='';for(const p of parts){const n=out?out+' '+p:p;if(n.length>max)break;out=n;}return (out||s.slice(0,max).replace(/\s+\S*$/u,'')).trim();}
