const title=clip(base.youtube_title||base.hook_overlay||base.title||'Business Media Project',70);
const description=clip(base.instagram_text||base.youtube_desc||base.tiktok_text||base.spoken_script||'Коротко о важном для предпринимателей.',160);
const hashtags=tags(base.instagram_hashtags||base.youtube_hashtags||base.tiktok_hashtags||'#бизнес #businessmedia #предприниматель',3);
const vkText=[description,hashtags].filter(Boolean).join('\n\n');
