  : 'echo "NO_TEMP_FILES"';
return {json:{...$json,ffmpeg_temp_files:unique,cleanup_command}};

const st=$json.data||$json;
const id=String(st.id||st.video_id||'');
const originals=$('HeyGen 1: Store Video ID').all().map(i=>i.json);
let base=originals.find(x=>String(x.heygen_video_id)===id);
base=base||$('HeyGen 1: Store Video ID').item.json;
