  heygen_status_raw:st
}};

const BASE_SPEED=1.2;
const TARGET_MAX_SECONDS=29.6; // запас перед жёстким лимитом 30.0
const HARD_MAX_SECONDS=35.0;
const rawPost=String($json.post_id||'post').replace(/[^a-zA-Z0-9_-]+/g,'_').slice(0,80);
const branch=Number($json.branch||0)||1;
const stamp=Date.now();
const raw=`/files/heygen_${rawPost}_b${branch}_${stamp}_captioned_raw.mp4`;
const final=`/files/heygen_${rawPost}_b${branch}_${stamp}_target30_hard35_blotato.mp4`;
const retry=`/files/heygen_${rawPost}_b${branch}_${stamp}_retry.mp4`;
const passlog=`/files/heygen_${rawPost}_b${branch}_${stamp}_2pass`;

// Blotato binary upload limit is 15 MB. Keep a real safety margin.
const TARGET_BYTES=13200000;
const HARD_MAX_BYTES=14500000;
const AUDIO_K=128;

function sh(v){ return `'${String(v).replace(/'/g, `'"'"'`)}'`; }

const cmd=[
  `ffmpeg -version >/dev/null 2>&1 || { echo "FFMPEG_NOT_FOUND"; exit 127; }`,
  `ffprobe -version >/dev/null 2>&1 || { echo "FFPROBE_NOT_FOUND"; exit 127; }`,
  `test -s ${sh(raw)} || { echo "RAW_FILE_NOT_FOUND=${raw}"; exit 1; }`,

  // Read real HeyGen duration and choose speed. Never slower than 1.2x.
  // If 1.2x would still exceed 29.6s, increase only as much as necessary.
  `duration=$(ffprobe -v error -show_entries format=duration -of default=nw=1:nk=1 ${sh(raw)}); ` +
  `test -n "$duration" || { echo "DURATION_NOT_FOUND"; exit 1; }; ` +
  `speed=$(awk -v d="$duration" -v base="${BASE_SPEED}" -v target="${TARGET_MAX_SECONDS}" 'BEGIN{need=d/target; s=(need>base?need:base); printf "%.5f", s}'); ` +
  `awk -v s="$speed" 'BEGIN{if(s>2.0) exit 0; exit 1}' && { echo "VIDEO_TOO_LONG_FOR_SAFE_ATEMPO_SPEED=$speed"; exit 6; } || true; ` +
  `outdur=$(awk -v d="$duration" -v s="$speed" 'BEGIN{printf "%.3f", d/s}'); ` +
  `total_k=$(awk -v bytes="${TARGET_BYTES}" -v d="$outdur" 'BEGIN{printf "%d", (bytes*8*0.94)/(d*1000)}'); ` +
  `video_k=$((total_k-${AUDIO_K}-40)); if [ "$video_k" -lt 450 ]; then video_k=450; fi; ` +
  `echo "INPUT_DURATION=$duration"; echo "VIDEO_SPEED=$speed"; echo "EXPECTED_OUTPUT_DURATION=$outdur"; echo "TARGET_VIDEO_KBPS=$video_k"`,

  // Adaptive resolution protects quality when the bitrate budget gets small.
  `if [ "$video_k" -ge 1900 ]; then out_w=1080; out_h=1920; ` +
  `elif [ "$video_k" -ge 850 ]; then out_w=720; out_h=1280; ` +
  `else out_w=540; out_h=960; fi; echo "OUTPUT_SIZE=\${out_w}x\${out_h}"`,

  // Two-pass H.264. HeyGen captions are already burned into frames.
  `vf="scale=$out_w:$out_h:force_original_aspect_ratio=decrease,pad=$out_w:$out_h:(ow-iw)/2:(oh-ih)/2,setsar=1,setpts=PTS/$speed"; ` +
  `ffmpeg -hide_banner -loglevel error -y -i ${sh(raw)} -vf "$vf" -an ` +
  `-c:v libx264 -preset medium -b:v "\${video_k}k" -maxrate "\${video_k}k" -bufsize "$((video_k*2))k" ` +
  `-pass 1 -passlogfile ${sh(passlog)} -f mp4 /dev/null && ` +
  `ffmpeg -hide_banner -loglevel error -y -i ${sh(raw)} ` +
  `-filter_complex "[0:v]$vf[v];[0:a]aresample=48000,atempo=$speed[a]" ` +
  `-map "[v]" -map "[a]" -map_metadata -1 ` +
  `-c:v libx264 -preset medium -b:v "\${video_k}k" -maxrate "\${video_k}k" -bufsize "$((video_k*2))k" ` +
  `-pass 2 -passlogfile ${sh(passlog)} -pix_fmt yuv420p ` +
  `-c:a aac -b:a ${AUDIO_K}k -ar 48000 -movflags +faststart ${sh(final)}`,

  `rm -f ${sh(passlog)}-0.log ${sh(passlog)}-0.log.mbtree ${sh(passlog)}.log ${sh(passlog)}.log.mbtree`,
  `test -s ${sh(final)} || { echo "FINAL_FILE_NOT_CREATED=${final}"; exit 1; }`,

  // Emergency size pass if muxing variance still lands over 14.5 MB.
  `size_bytes=$(wc -c < ${sh(final)}); if [ "$size_bytes" -gt "${HARD_MAX_BYTES}" ]; then ` +
  `echo "EMERGENCY_REENCODE_ORIGINAL_SIZE=$size_bytes"; ` +
  `retry_k=$((video_k*75/100)); if [ "$retry_k" -lt 350 ]; then retry_k=350; fi; ` +
  `ffmpeg -hide_banner -loglevel error -y -i ${sh(raw)} ` +
  `-filter_complex "[0:v]scale=720:1280:force_original_aspect_ratio=decrease,pad=720:1280:(ow-iw)/2:(oh-ih)/2,setsar=1,setpts=PTS/$speed[v];[0:a]aresample=48000,atempo=$speed[a]" ` +
  `-map "[v]" -map "[a]" -map_metadata -1 -c:v libx264 -preset medium ` +
  `-b:v "\${retry_k}k" -maxrate "\${retry_k}k" -bufsize "$((retry_k*2))k" -pix_fmt yuv420p ` +
  `-c:a aac -b:a 96k -ar 48000 -movflags +faststart ${sh(retry)} && mv ${sh(retry)} ${sh(final)}; fi`,

  `final_size=$(wc -c < ${sh(final)}); ` +
  `if [ "$final_size" -gt "${HARD_MAX_BYTES}" ]; then echo "BLOTATO_FILE_STILL_TOO_LARGE=$final_size"; exit 4; fi`,

  // ABSOLUTE DURATION GATE. No file >30.0s can reach Blotato/VK.
  `final_duration=$(ffprobe -v error -show_entries format=duration -of default=nw=1:nk=1 ${sh(final)}); ` +
  `test -n "$final_duration" || { echo "FINAL_DURATION_NOT_FOUND"; exit 1; }; ` +
