  `test -n "$duration" || { echo "DURATION_NOT_FOUND"; exit 1; }; ` +
  `speed=$(awk -v d="$duration" -v base="${BASE_SPEED}" -v target="${TARGET_MAX_SECONDS}" 'BEGIN{need=d/target; s=(need>base?need:base); printf "%.5f", s}'); ` +
  `awk -v s="$speed" 'BEGIN{if(s>2.0) exit 0; exit 1}' && { echo "VIDEO_TOO_LONG_FOR_SAFE_ATEMPO_SPEED=$speed"; exit 6; } || true; ` +
