  `total_k=$(awk -v bytes="${TARGET_BYTES}" -v d="$outdur" 'BEGIN{printf "%d", (bytes*8*0.94)/(d*1000)}'); ` +
  `video_k=$((total_k-${AUDIO_K}-40)); if [ "$video_k" -lt 450 ]; then video_k=450; fi; ` +
  `echo "INPUT_DURATION=$duration"; echo "VIDEO_SPEED=$speed"; echo "EXPECTED_OUTPUT_DURATION=$outdur"; echo "TARGET_VIDEO_KBPS=$video_k"`,

  // Adaptive resolution protects quality when the bitrate budget gets small.
  `if [ "$video_k" -ge 1900 ]; then out_w=1080; out_h=1920; ` +
