  `ffmpeg -hide_banner -loglevel error -y -i ${sh(raw)} -vf "$vf" -an ` +
  `-c:v libx264 -preset medium -b:v "\${video_k}k" -maxrate "\${video_k}k" -bufsize "$((video_k*2))k" ` +
  `-pass 1 -passlogfile ${sh(passlog)} -f mp4 /dev/null && ` +
  `ffmpeg -hide_banner -loglevel error -y -i ${sh(raw)} ` +
  `-filter_complex "[0:v]$vf[v];[0:a]aresample=48000,atempo=$speed[a]" ` +
  `-map "[v]" -map "[a]" -map_metadata -1 ` +
  `-c:v libx264 -preset medium -b:v "\${video_k}k" -maxrate "\${video_k}k" -bufsize "$((video_k*2))k" ` +
  `-pass 2 -passlogfile ${sh(passlog)} -pix_fmt yuv420p ` +
  `-c:a aac -b:a ${AUDIO_K}k -ar 48000 -movflags +faststart ${sh(final)}`,

