  `echo "EMERGENCY_REENCODE_ORIGINAL_SIZE=$size_bytes"; ` +
  `retry_k=$((video_k*75/100)); if [ "$retry_k" -lt 350 ]; then retry_k=350; fi; ` +
  `ffmpeg -hide_banner -loglevel error -y -i ${sh(raw)} ` +
  `-filter_complex "[0:v]scale=720:1280:force_original_aspect_ratio=decrease,pad=720:1280:(ow-iw)/2:(oh-ih)/2,setsar=1,setpts=PTS/$speed[v];[0:a]aresample=48000,atempo=$speed[a]" ` +
  `-map "[v]" -map "[a]" -map_metadata -1 -c:v libx264 -preset medium ` +
  `-b:v "\${retry_k}k" -maxrate "\${retry_k}k" -bufsize "$((retry_k*2))k" -pix_fmt yuv420p ` +
  `-c:a aac -b:a 96k -ar 48000 -movflags +faststart ${sh(retry)} && mv ${sh(retry)} ${sh(final)}; fi`,

  `final_size=$(wc -c < ${sh(final)}); ` +
  `if [ "$final_size" -gt "${HARD_MAX_BYTES}" ]; then echo "BLOTATO_FILE_STILL_TOO_LARGE=$final_size"; exit 4; fi`,

  // ABSOLUTE DURATION GATE. No file >30.0s can reach Blotato/VK.
  `final_duration=$(ffprobe -v error -show_entries format=duration -of default=nw=1:nk=1 ${sh(final)}); ` +
  `test -n "$final_duration" || { echo "FINAL_DURATION_NOT_FOUND"; exit 1; }; ` +
  `if awk -v d="$final_duration" -v max="${HARD_MAX_SECONDS}" 'BEGIN{exit !(d>max)}'; then ` +
  `echo "DURATION_GUARD_FAILED=$final_duration"; rm -f ${sh(final)}; exit 5; fi; ` +
  `echo "FINAL_DURATION=$final_duration"`,

  `rm -f ${sh(raw)} ${sh(retry)}`,
  `echo "HEYGEN_CAPTIONS_PRESERVED=true"`,
  `echo "BLOTATO_BINARY_SAFE=true"`,
  `echo "MAX_DURATION_SECONDS=${HARD_MAX_SECONDS}"`,
  `echo "FINAL_FILE=${final}"`,
  `echo "FINAL_SIZE_BYTES=$final_size"`
].join('\n');

